def dedupe_tests(tests, names):
    # Keep the TestCase entries whose name is in `names`, deduping by name and
    # preserving the original order.
    seen = set()
    selected = []
    for test in tests:
        if test.name in names and test.name not in seen:
            seen.add(test.name)
            selected.append(test)
    return selected


